    private String paymentMethod() {
        if (gcashRadio.isSelected()) return Order.GCASH;
        if (bankRadio.isSelected()) return Order.BANK_TRANSFER;
        return Order.CASH;
    }

    private void refresh() {
        Ui.select(cashCard, cashRadio.isSelected());
        Ui.select(gcashCard, gcashRadio.isSelected());
        Ui.select(bankCard, bankRadio.isSelected());
    }

    /** Asks for the GCash / bank reference number used as proof of payment. Returns null if cancelled. */
    private String askReference(String method) {
        String message = "<html>Send <b>" + Ui.pesoHtml(Session.getDraftTotal()) + "</b> via " + method + " to:<br><b>"
                + Session.paymentAccount(method) + "</b><br><br>Then enter the reference number of your payment.<br>"
                + "Staff will verify it before marking your order as paid.</html>";
        while (true) {
            String reference = javax.swing.JOptionPane.showInputDialog(this, message, "Proof of Payment",
                    javax.swing.JOptionPane.INFORMATION_MESSAGE);
            if (reference == null) {
                return null;
            }
            reference = reference.trim();
            if (reference.matches("[A-Za-z0-9-]{4,30}")) {
                return reference;
            }
            Ui.warn(this, "Please enter the reference number shown on your " + method + " receipt (4-30 letters or digits).");
        }
    }

    private void proceed() {
        String method = paymentMethod();
        String reference = "";
        if (!Order.CASH.equals(method)) {
            reference = askReference(method);
            if (reference == null) {
                return;
            }
        }
        Order order = Session.placeOrder(method, reference);
        Ui.showReceipt(this, order);
        Nav.open(this, new MyOrdersForm());
    }

    public static void main(String args[]) {
        Ui.installLookAndFeel();
        if (!Database.start()) { // connects to MySQL and creates the tables on first run
            return;
        }
        Session.ensurePreviewUser(); // lets this screen run on its own (Shift+F6)
        java.awt.EventQueue.invokeLater(() -> new PaymentForm().setVisible(true));
    }

